#include <stdio.h>
#include <stdlib.h>

typedef struct Node { int data; struct Node *next; } Node;

Node *push_front(Node *head, int v) {
    Node *n = malloc(sizeof(Node));
    n->data = v; n->next = head;
    return n;
}

/* 迭代反转：先保存后继，再掉转方向 */
Node *reverse(Node *head) {
    Node *prev = NULL, *cur = head;
    while (cur) {
        Node *next = cur->next;
        cur->next = prev;
        prev = cur;
        cur = next;
    }
    return prev;
}

void print_list(const char *tag, Node *head) {
    printf("%s: ", tag);
    for (Node *p = head; p; p = p->next)
        printf("%d%s", p->data, p->next ? " -> " : "");
    printf("\n");
}

void free_list(Node *head) {
    while (head) { Node *n = head->next; free(head); head = n; }
}

int main(void) {
    Node *head = NULL;
    for (int i = 5; i >= 1; i--) head = push_front(head, i);
    print_list("原链表", head);
    head = reverse(head);
    print_list("反转后", head);
    free_list(head);
    return 0;
}
